import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
import optax

class RMSNorm(nn.Module):
    eps: float = 1e-6
    @nn.compact
    def __call__(self, x):
        C = x.shape[-1]
        scale = self.param('scale', nn.initializers.ones, (C,))
        rms = jnp.sqrt(jnp.mean(jnp.square(x), axis=-1, keepdims=True) + self.eps)
        return (x / rms) * scale

class DSConvBlockRMS(nn.Module):
    d_model:int; kernel_size:int; dropout_rate:float; dilation:int=1
    @nn.compact
    def __call__(self, x, deterministic=True):
        residual = x
        y = RMSNorm()(x)
        y = nn.Conv(features=self.d_model, kernel_size=(self.kernel_size,),
                    feature_group_count=self.d_model, padding='SAME',
                    kernel_dilation=(self.dilation,))(y)
        y = nn.gelu(y)
        z = nn.Dense(2*self.d_model)(y)
        a,g = jnp.split(z,2,axis=-1)
        y = a * nn.sigmoid(g)
        y = nn.Dropout(rate=self.dropout_rate)(y, deterministic=deterministic)
        return residual + y

class AttnPoolTempRMS(nn.Module):
    d_model:int; heads:int=4; tau:float=0.5
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = RMSNorm()(x)
        logits = nn.tanh(nn.Dense(self.d_model)(h))
        logits = nn.Dense(self.heads)(logits)
        w = nn.softmax(logits / self.tau, axis=1)
        pooled_heads = jnp.einsum('blh,blc->bhc', w, h)
        return pooled_heads.mean(axis=1)

class Net(nn.Module):
    d_output:int; task_type:str
    d_model:int=256; blocks:int=5; k:int=7; dropout:float=0.1
    heads:int=4; dilations:tuple=(1,2,4,8,16)
    @nn.compact
    def __call__(self, x, deterministic=True):
        # No positional encoding
        h = nn.Dense(self.d_model)(x)
        h = nn.gelu(h)
        h = nn.Dropout(rate=self.dropout)(h, deterministic=deterministic)
        for i in range(self.blocks):
            h = DSConvBlockRMS(self.d_model, self.k, self.dropout,
                               dilation=self.dilations[i%len(self.dilations)])(h, deterministic=deterministic)
        mean = jnp.mean(h, axis=1)
        attn = AttnPoolTempRMS(self.d_model, heads=self.heads, tau=0.5)(h, deterministic=deterministic)
        z = jnp.concatenate([mean, attn], axis=-1)
        z = RMSNorm()(z)
        z = nn.Dense(self.d_model)(z); z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout)(z, deterministic=deterministic)
        logits = nn.Dense(self.d_output)(z)
        return logits.squeeze(-1) if (self.task_type=='regression' and self.d_output==1) else logits

class Wrap:
    def __init__(self, **kw): self.net = Net(**kw)
    def init(self, rng_key, dummy):
        pk, dk = random.split(rng_key)
        vars = self.net.init({'params':pk,'dropout':dk}, dummy, deterministic=True)
        return vars['params']
    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic: return self.net.apply({'params':params}, x, deterministic=True)
        if rng_key is None: rng_key = random.PRNGKey(0)
        return self.net.apply({'params':params}, x, deterministic=False, rngs={'dropout':rng_key})

def _define_hyperparameters():
    return {'learning_rate':0.001,'d_model':256,'num_blocks':5,'kernel_size':7,'dropout_rate':0.1,
            'attn_heads':4,'dilations':(1,2,4,8,16)}

def create_network(hp):
    return Wrap(d_output=hp.get('d_output',1), task_type=hp.get('task_type','regression'),
                d_model=hp.get('d_model',256), blocks=hp.get('num_blocks',5), k=hp.get('kernel_size',7),
                dropout=hp.get('dropout_rate',0.1), heads=hp.get('attn_heads',4),
                dilations=tuple(hp.get('dilations',(1,2,4,8,16))))

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(optax.clip_by_global_norm(1.0), optax.adamw(learning_rate=learning_rate, weight_decay=0.01))

BASE_SEED=42; BATCH_SIZE=64

